mapper.select:
where SUBITEM.LATESTREVISION LIKE 'm%' AND BOMVIEW.NAME = 'BOM'
AND SUBITEM.GUID = #{end1}
union all
where LEVEL <= 20 START WITH
x.viewfk = #{guid}
AND x.viewfkname = 'BOM' CONNECT BY PRIOR x.subguid = x.parentguid AND PRIOR x.viewfkname = x.viewfkname) b ORDER BY LPAD (b.SEQUENCE, 32, '0')
